let results = [];

for (const item of $input.all()) {
  for (const key of Object.keys(item.binary || {})) {
    const file = item.binary[key];

    results.push({
      json: {
        fileName: file.fileName,
        mimeType: file.mimeType,
        fileExtension: file.fileExtension
      },
      binary: {
        FileType: file
      }
    });
  }
}

return results;

const ergebnis = [];
const eingaben = $input.all();

for (let i = 0; i < eingaben.length; i++) {
  const item = eingaben[i];
  const angebot = item.json.output ?? item.json;

  // Ursprungsdatei eindeutig zuordnen
  const datei = $('Hash-Abgleich mit Notion').itemMatching(i).json;

  const dateiname = datei.fileName ?? "";
  const dateiHash = datei.FileHash ?? "";

  if (!dateiname || !dateiHash) {
    throw new Error(
      `Dateiname oder SHA-256-Hash fehlt bei Eingabe ${i + 1}`
    );
  }

  // Angebotsbezogene Hinweise zusammenstellen
  const hinweise = [];

  if (angebot.besondere_hinweise) {
    hinweise.push(angebot.besondere_hinweise);
  }

  if (angebot.ausfuehrungszeitraum) {
    hinweise.push(
      "Ausführungszeitraum: " + angebot.ausfuehrungszeitraum
    );
  }

  if (angebot.zwischensumme !== undefined &&
      angebot.zwischensumme !== null) {
    hinweise.push(
      "Zwischensumme: " + angebot.zwischensumme + " €"
    );
  }

  if (angebot.mehrwertsteuer !== undefined &&
      angebot.mehrwertsteuer !== null) {
    hinweise.push(
      "Mehrwertsteuerbetrag: " + angebot.mehrwertsteuer + " €"
    );
  }

  // Jede Leistungsposition einzeln ausgeben
  for (const position of angebot.positionen ?? []) {
    ergebnis.push({
      json: {
        dateiname: dateiname,
        dateiHash: dateiHash,

        anbieter: angebot.anbieter ?? "",
        datum: angebot.angebotsdatum ?? "",
        projekt: angebot.projektbezeichnung ?? "",
        leistung: position.leistung ?? "",

        menge_einheit: position.menge_einheit ?? "",
        einheitspreis: position.einheitspreis ?? null,
        positionspreis: position.preis ?? null,

        gesamtpreis: angebot.gesamtpreis ?? null,
        hinweise: hinweise.join("; ")
      },
      pairedItem: { item: i }
    });
  }
}

return ergebnis;

const angebote = new Map();

for (const item of $input.all()) {
  const daten = item.json;

  const anbieter = daten.property_name ?? daten.name ?? "";
  const datum = daten.property_datum?.start ?? "";
  const projekt = daten.property_projekt ?? "";
  const gesamtpreis = daten.property_gesamtpreis ?? null;
  const hinweise = daten.property_hinweise ?? "";

  // Vorhandene Angebotsnummer aus Hinweisen erkennen
  const angebotsnummer =
    hinweise.match(/Angebotsnummer:\s*([^;,]+)/i)?.[1]?.trim() ?? "";

  // Gruppierung anhand der vorhandenen Angebotsinformationen
  const schluessel = JSON.stringify([
    anbieter,
    datum,
    projekt,
    angebotsnummer,
    gesamtpreis,
    hinweise
  ]);

  // Angebot einmalig anlegen
  if (!angebote.has(schluessel)) {
    angebote.set(schluessel, {
      anbieter,
      angebotsdatum: datum,
      projekt,
      angebotsnummer,
      gesamtpreis,
      hinweise,
      positionen: []
    });
  }

  const angebot = angebote.get(schluessel);

  // Einzelne Leistungsposition übernehmen
  const leistung = daten.property_position ?? "";

  if (leistung) {
    angebot.positionen.push({
      leistung,
      menge_einheit: daten.property_menge_einheit ?? "",
      einheitspreis: daten.property_einheitspreis ?? null,
      positionspreis: daten.property_positionspreis ?? null
    });
  }
}

// Alle Angebote in einem einzigen Item zusammenfassen
return [
  {
    json: {
      angebote: Array.from(angebote.values())
    }
  }
];

const dateien = $('Merge').all();
const notionDaten = $input.all();

const gespeicherteHashes = new Set();
const bereitsGeprueft = new Set();

// Vorhandene SHA-256-Hashwerte aus Notion lesen
for (const item of notionDaten) {
  const seite = item.json;

  // Leere Notion-Datenbank
  if (!seite || Object.keys(seite).length === 0) {
    continue;
  }

  const eigenschaft = seite.properties?.DateiHash;

  if (!eigenschaft || !Array.isArray(eigenschaft.rich_text)) {
    throw new Error("Notion-DateiHash fehlt oder ist ungültig.");
  }

  const hash = eigenschaft.rich_text
    .map(eintrag =>
      eintrag.plain_text ?? eintrag.text?.content ?? ""
    )
    .join("")
    .trim()
    .toLowerCase();

  if (!hash) {
    throw new Error("Ein Notion-Datensatz enthält keinen DateiHash.");
  }

  gespeicherteHashes.add(hash);
}

// Originaldateien mit den Notion-Hashwerten vergleichen
const neueDateien = [];

for (const datei of dateien) {
  const hash = String(datei.json.FileHash ?? "")
    .trim()
    .toLowerCase();

  if (!hash) {
    throw new Error("SHA-256-Hashwert der Datei fehlt.");
  }

  if (gespeicherteHashes.has(hash) ||
      bereitsGeprueft.has(hash)) {
    continue;
  }

  bereitsGeprueft.add(hash);

  neueDateien.push({
    json: datei.json,
    binary: datei.binary,
    pairedItem: { item: 0 }
  });
}

return neueDateien;
